// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, pinLink, getLinkPin, deleteLink } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "description": "",
        "name": "skyramp-pin-rejections",
        "tags": [],
        "type": "url",
        "url": "https://example.com/skyramp-pin-rejections"
    }`;

    const linksPostResponse = await createLink(client, headers, linksPostRequestBody, 200);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    const linkId = getResponseValue(linksPostResponse, "response.id");
    const callerId = getResponseValue(linksPostResponse, "response.createdById");
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("skyramp-pin-rejections");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/skyramp-pin-rejections");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(linkId, 'link id').toBeGreaterThan(0);

    const linksPinPatchResponse = await pinLink(client, headers, linkId, 200);
    expect(linksPinPatchResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPinPatchResponse, "response.id"), 'pinned link id').toBe(linkId);
    expect(getResponseValue(linksPinPatchResponse, "response.name"), 'pinned link name').toBe("skyramp-pin-rejections");
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy.0.id"), 'pinnedBy first entry').toBe(callerId);
    expect(getResponseValue(linksPinPatchResponse, "response.pinnedBy.1"), 'pinnedBy second entry').toBeNull();

    const abcPinPatchResponse = await pinLink(client, headers, "abc", 400);
    expect(abcPinPatchResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcPinPatchResponse, "response"), 'non-numeric id message').toBe("Invalid link ID.");

    const links999999999PinPatchResponse = await pinLink(client, headers, "999999999", 404);
    expect(links999999999PinPatchResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(links999999999PinPatchResponse, "response"), 'unknown id message').toBe("Link not found.");

    const linksPinGetResponse = await getLinkPin(client, headers, linkId, 405);
    expect(linksPinGetResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(linksPinGetResponse, "response"), 'method not allowed message').toBe("Method not allowed.");

    const unauthenticatedHeaders: Record<string, string> = {};
    const linksPinPatchUnauthenticatedResponse = await pinLink(client, unauthenticatedHeaders, linkId, 401);
    expect(linksPinPatchUnauthenticatedResponse.statusCode, 'status code').toBe(401);
    expect(getResponseValue(linksPinPatchUnauthenticatedResponse, "response"), 'unauthenticated message').toBe("You must be logged in.");

    const linksPinPatch1Response = await pinLink(client, headers, linkId, 200);
    expect(linksPinPatch1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPinPatch1Response, "response.id"), 'unpinned link id').toBe(linkId);
    expect(getResponseValue(linksPinPatch1Response, "response.pinnedBy.0"), 'pinnedBy after unpin').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, headers, linkId, 200);
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link id').toBe(linkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'deleted link name').toBe("skyramp-pin-rejections");

    const pinPatchResponse = await pinLink(client, headers, "1.5", 400);
    expect(pinPatchResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(pinPatchResponse, "response"), 'non-integer id message').toBe("Invalid link ID.");
});
